const links=[['management/','◫','Management'],['otc-desk.html','⌁','OTC Desk'],['treasury.html','▤','Finance / Treasury'],['compliance.html','✓','Compliance / AML'],['corporate-client.html','◉','Corporate Client']];
function pill(value){const c=/Settled|Reconciled|Approved|Active|Verified|Clear/.test(value)?'ok':/Processing|Pending|Review|locked/.test(value)?'pending':/Alert|Hold|Escalate/.test(value)?'alert':'pending';return `<span class="pill ${c}">${value}</span>`}
function table(t){return `<div class="card"><h2>${t[0]}</h2><div class="table-wrap"><table class="table"><thead><tr>${t[1].map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${t[2].map(row=>`<tr>${row.map((x,i)=>`<td class="${i===0?'mono':''}">${i===row.length-1?pill(x):x}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div>`}
function nav(key){return links.map(([href,icon,label])=>`<a href="${href}" class="${href.startsWith(key)?'active':''}"><i>${icon}</i>${label}</a>`).join('')}
function renderModule(){const app=document.querySelector('#module-app');if(!app)return;const key=document.body.dataset.module,d=portalData[key];app.innerHTML=`<div class="demo">DEMO DATA — NOT FOR PRODUCTION OR SETTLEMENT RELIANCE</div><div class="shell"><aside class="side"><div class="brand"><div class="mark">LBP</div><div>PT LINTAS BATAS<small>PEMBAYARAN · OTC</small></div></div><div class="caption">ROLE MODULES</div><nav class="nav">${nav(key)}</nav><div class="side-foot">Separate static module<br>Ready for future subdomain mapping.</div></aside><main class="main"><header class="top"><a class="back" href="index.html">← Back to public landing page</a><div class="profile"><span>${d.title}</span><span class="avatar">LBP</span></div></header><section class="content"><div class="heading"><div><h1>${d.title}</h1><p>${d.subtitle}</p></div><button class="button">Export demo report</button></div><div class="kpis">${d.kpis.map(k=>`<div class="kpi"><label>${k[0]}</label><strong>${k[1]}</strong><span>${k[2]}</span></div>`).join('')}</div><div class="grid2"><div>${table(d.tables[0])}</div><div class="card"><h2>Module control</h2><p>This page is a separate static HTML module. It is prepared for a dedicated subdomain and remains connected to synthetic, browser-only demonstration data.</p><div class="notice">Before production use, connect authenticated identity, role enforcement, governed data, compliance controls and server-side audit evidence.</div>${['Ledger visibility','Role-specific workflow','Export controls','Audit boundary'].map((x,i)=>`<div class="row"><span>${x}</span><div class="bar"><i style="width:${92-i*9}%"></i></div><b>${i===3?'Demo':'Enabled'}</b></div>`).join('')}</div></div><div style="margin-top:14px">${table(d.tables[1])}</div></section></main></div>`}
function applyBranding(){const logoStyles=document.createElement('link');logoStyles.rel='stylesheet';logoStyles.href='logo.css';document.head.append(logoStyles);document.querySelectorAll('.side .brand').forEach(brand=>{brand.className='brand has-logo';brand.innerHTML='<img class="logo-lockup" src="assets/lbp-crypto-fiat-logo.png" alt="LBP crypto-to-fiat conversion logo"><div>PT LINTAS BATAS<small>PEMBAYARAN · OTC</small></div>'})}
const moduleTheme=document.createElement('link');moduleTheme.rel='stylesheet';moduleTheme.href='modules-institutional.css';document.head.append(moduleTheme);
renderModule();applyBranding();
